    def merge_markets(self, newMarkets: List[Market]):
        existingMarkets = [] if (self.markets is None) else list(self.markets.values())
        combined = self.array_concat(existingMarkets, newMarkets)
        self.set_markets(combined)

    def is_market_symbol_cached(self, symbol: str) -> bool:
        if self.markets is None:
            return False
        return symbol in self.markets

    def remove_cached_market_symbol(self, symbol: str):
        if self.markets is None:
            return
        if symbol in self.markets:
            del self.markets[symbol]

    def resolve_markets(self, symbols: List[str], params={}) -> dict:
        marketsBySymbol: dict = {}
        pendingSymbols = []
        newMarkets: List[Market] = []
        marketsDict = {} if (self.markets is None) else self.markets
        for symbolIndex in range(0, len(symbols)):
            symbol = symbols[symbolIndex]
            if symbol in marketsDict:
                marketsBySymbol[symbol] = self.market(symbol)
                continue
            pendingSymbols.append(symbol)
        if len(pendingSymbols) > 0:
            if self.has_available_pairs_cache():
                self.fetch_available_pairs(params)
        for pendingIndex in range(0, len(pendingSymbols)):
            symbol = pendingSymbols[pendingIndex]
            pairId = self.symbol_to_pair_id(symbol)
            if pairId is None:
                raise BadSymbol(self.id + ' does not have market ' + symbol)
            if self.has_available_pairs_cache() and not self.is_pair_available(pairId):
                raise BadSymbol(self.id + ' does not have market ' + symbol)
            parts = symbol.split('/')
            baseComposite = self.code_to_composite(self.safe_string(parts, 0))
            quoteComposite = self.code_to_composite(self.safe_string(parts, 1))
            if baseComposite is None or quoteComposite is None:
                raise BadSymbol(self.id + ' does not have market ' + symbol)
            market = self.parse_market_from_composites(baseComposite, quoteComposite)
            newMarkets.append(market)
            marketsBySymbol[symbol] = market
        if len(newMarkets) > 0:
            self.merge_markets(newMarkets)
            for pendingIndex in range(0, len(pendingSymbols)):
                symbol = pendingSymbols[pendingIndex]
                marketsBySymbol[symbol] = self.market(symbol)
        return {
            'marketsBySymbol': marketsBySymbol,
        }

    def resolve_market(self, symbol: str, params={}) -> Market:
        resolveResult = self.resolve_markets([symbol], params)
        return resolveResult['marketsBySymbol'][symbol]

    def fetch_currencies(self, params={}) -> Currencies:
        """
        fetches all available currencies on SimpleSwap

        https://api.simpleswap.io/docs/api-reference/currencies

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: an associative dictionary of currencies
        """
        self.check_required_credentials()
        response = self.publicGetV3Currencies(params)
        currencies = self.to_array(response)
        result: dict = {}
        for currencyIndex in range(0, len(currencies)):
            currency = currencies[currencyIndex]
            ticker = self.safe_string(currency, 'ticker')
            network = self.safe_string(currency, 'network')
            if ticker is None or network is None:
                continue
            isFiat = self.safe_bool(currency, 'isFiat', False)
            if isFiat:
                continue
            composite = ticker + ':' + network
            code = self.composite_to_code(composite)
            precisionValue = self.safe_integer(currency, 'precision')
            precision = None
            if precisionValue is not None:
                precision = self.parse_number(self.parse_precision(self.number_to_string(precisionValue)))
            result[code] = self.safe_currency_structure({
                'id': composite,
                'code': code,
                'name': self.safe_string(currency, 'name'),
                'active': True,
                'deposit': True,
                'withdraw': True,
                'fee': None,
                'precision': precision,
                'limits': {
                    'amount': {'min': None, 'max': None},
                    'withdraw': {'min': None, 'max': None},
                },
                'info': currency,
            })
        return result

