    def ob_load_markets_for_symbols(self, symbols: List[str], reload=False, params={}) -> List[dict]:
        """
        lazily resolves and populates self.markets for the given symbols

        https://api.simpleswap.io/docs/api-reference/pairs

        :param str[] symbols: list of unified market symbols
        :param boolean reload: when True, re-fetch symbols even if already cached in self.markets
        :param dict params: extra parameters specific to the exchange API endpoint
        :returns dict[]: empty list; ob_simpleswap returns fixed market status structures
        """
        if symbols is None:
            raise ArgumentsRequired(self.id + ' obLoadMarketsForSymbols() requires a non-empty symbols argument')
        symbolsLength = len(symbols)
        if symbolsLength == 0:
            raise ArgumentsRequired(self.id + ' obLoadMarketsForSymbols() requires a non-empty symbols argument')
        self.check_required_credentials()
        self.load_markets()
        symbolsToResolve = []
        for symbolIndex in range(0, symbolsLength):
            symbol = symbols[symbolIndex]
            if reload:
                self.remove_cached_market_symbol(symbol)
                symbolsToResolve.append(symbol)
            elif not self.is_market_symbol_cached(symbol):
                symbolsToResolve.append(symbol)
        if len(symbolsToResolve) > 0:
            self.fetch_available_pairs(params, reload)
            self.resolve_markets(symbolsToResolve, params)
        return []

    def fetch_ticker(self, symbol: str, params={}) -> Ticker:
        """
        fetches a price ticker / estimate for a swap pair on SimpleSwap

        https://api.simpleswap.io/docs/api-reference/estimates

        :param str symbol: unified market symbol, e.g. 'BTC@BTC/ETH@ETH'
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.amount]: amount to estimate, defaults to '1'
        :param boolean [params.fixed]: if True, use fixed-rate flow estimation
        :param boolean [params.reverse]: if True, amount is receive amount
        :returns dict: a `ticker structure <https://docs.ccxt.com/?id=ticker-structure>`
        """
        self.check_required_credentials()
        self.load_markets()
        resolveResult = self.resolve_markets([symbol], params)
        market = resolveResult['marketsBySymbol'][symbol]
        marketInfo = self.safe_dict(market, 'info', {})
        tickerFrom = self.safe_string(marketInfo, 'tickerFrom')
        networkFrom = self.safe_string(marketInfo, 'networkFrom')
        tickerTo = self.safe_string(marketInfo, 'tickerTo')
        networkTo = self.safe_string(marketInfo, 'networkTo')
        amount = self.safe_string(params, 'amount', '1')
        fixed = self.safe_bool(params, 'fixed', False)
        reverse = self.safe_bool(params, 'reverse', False)
        params = self.omit(params, ['amount', 'fixed', 'reverse'])
        request: dict = {
            'tickerFrom': tickerFrom,
            'networkFrom': networkFrom,
            'tickerTo': tickerTo,
            'networkTo': networkTo,
            'amount': amount,
            'fixed': fixed,
            'reverse': reverse,
        }
        response = self.publicGetV3Estimates(self.extend(request, params))
        return self.parse_ticker(response, market)

