    def create_order(self, symbol: str, type: OrderType, side: OrderSide, amount: float, price: Num = None, params={}) -> Order:
        """
        create a swap order on SimpleSwap(requires API key)

        https://api.simpleswap.io/docs/api-reference/exchanges

        :param str symbol: unified market symbol, e.g. 'BTC@BTC/ETH@ETH'
        :param str type: order type – only 'market' is supported(floating rate), or 'limit' for fixed-rate
        :param str side: 'buy' or 'sell' – for swaps self is always 'sell'(sell base for quote)
        :param float amount: amount of the base currency to send
        :param float [price]: not used for SimpleSwap standard flow
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str params['address_to']: destination address for the quote currency(required)
        :param str [params.extraIdTo]: extra id or memo for the destination address
        :param str [params.userRefundAddress]: refund address for the base currency
        :param str [params.userRefundExtraId]: extra id or memo for the refund address
        :param str [params.rateId]: rate id from fixed-rate estimate(required for fixed-rate)
        :param boolean [params.fixed]: if True, create a fixed-rate exchange
        :param boolean [params.reverse]: if True, amount is receive amount
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        self.check_required_credentials()
        self.load_markets()
        resolveResult = self.resolve_markets([symbol], params)
        market = resolveResult['marketsBySymbol'][symbol]
        marketInfo = self.safe_dict(market, 'info', {})
        addressTo = self.safe_string(params, 'address_to')
        if addressTo is None:
            raise ArgumentsRequired(self.id + ' createOrder() requires params.address_to – the destination address for the received currency')
        request: dict = {
            'tickerFrom': self.safe_string(marketInfo, 'tickerFrom'),
            'networkFrom': self.safe_string(marketInfo, 'networkFrom'),
            'tickerTo': self.safe_string(marketInfo, 'tickerTo'),
            'networkTo': self.safe_string(marketInfo, 'networkTo'),
            'amount': self.number_to_string(amount),
            'addressTo': addressTo,
        }
        extraIdTo = self.safe_string(params, 'extraIdTo')
        if extraIdTo is not None:
            request['extraIdTo'] = extraIdTo
        userRefundAddress = self.safe_string(params, 'userRefundAddress')
        if userRefundAddress is not None:
            request['userRefundAddress'] = userRefundAddress
        userRefundExtraId = self.safe_string(params, 'userRefundExtraId')
        if userRefundExtraId is not None:
            request['userRefundExtraId'] = userRefundExtraId
        rateId = self.safe_string(params, 'rateId')
        if rateId is not None:
            request['rateId'] = rateId
        fixed = self.safe_bool(params, 'fixed')
        if fixed is not None:
            request['fixed'] = fixed
        reverse = self.safe_bool(params, 'reverse')
        if reverse is not None:
            request['reverse'] = reverse
        params = self.omit(params, ['address_to', 'extraIdTo', 'userRefundAddress', 'userRefundExtraId', 'rateId', 'fixed', 'reverse'])
        response = self.publicPostV3Exchanges(self.extend(request, params))
        return self.parse_order(response, market)

