    def parse_order(self, order: dict, market: Market = None) -> Order:
        id = self.safe_string_2(order, 'publicId', 'id')
        tickerFrom = self.safe_string(order, 'tickerFrom')
        networkFrom = self.safe_string(order, 'networkFrom')
        tickerTo = self.safe_string(order, 'tickerTo')
        networkTo = self.safe_string(order, 'networkTo')
        parsedSymbol = None
        if tickerFrom is not None and networkFrom is not None and tickerTo is not None and networkTo is not None:
            baseComposite = tickerFrom + ':' + networkFrom
            quoteComposite = tickerTo + ':' + networkTo
            parsedSymbol = self.build_symbol_from_composites(baseComposite, quoteComposite)
        symbol = self.safe_symbol(None, market)
        if symbol is None:
            symbol = parsedSymbol
        rawStatus = self.safe_string(order, 'status')
        status = None
        if rawStatus is not None:
            status = self.parse_order_status(rawStatus)
        else:
            status = 'open'
        amountFrom = self.safe_string(order, 'amountFrom')
        amountTo = self.safe_string(order, 'amountTo')
        createdAt = self.safe_string(order, 'createdAt')
        updatedAt = self.safe_string(order, 'updatedAt')
        timestamp = self.parse8601(createdAt)
        lastUpdateTimestamp = self.parse8601(updatedAt)
        return self.safe_order({
            'id': id,
            'clientOrderId': None,
            'info': order,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'lastTradeTimestamp': None,
            'lastUpdateTimestamp': lastUpdateTimestamp,
            'symbol': symbol,
            'type': 'market',
            'timeInForce': None,
            'postOnly': None,
            'side': 'sell',
            'price': amountTo,
            'stopPrice': None,
            'triggerPrice': None,
            'amount': amountFrom,
            'cost': None,
            'average': None,
            'filled': None,
            'remaining': None,
            'status': status,
            'fee': {
                'currency': None,
                'cost': None,
                'rate': None,
            },
            'trades': None,
        }, market)

    def parse_order_status(self, status: Str) -> Str:
        statuses: dict = self.safe_dict(self.options, 'statusMapping', {})
        return self.safe_string(statuses, status, status)

    def sign(self, path, api='public', method='GET', params={}, headers=None, body=None):
        self.check_required_credentials(False)
        url = self.urls['api']['rest'] + '/' + self.implode_params(path, params)
        query = self.omit(params, self.extract_params(path))
        apiKey = self.resolve_api_key()
        headers = {} if (headers is None) else headers
        headers['x-api-key'] = apiKey
        if method == 'GET':
            if query:
                url += '?' + self.urlencode(query)
        elif method == 'POST':
            if query:
                body = self.json(query)
                headers['Content-Type'] = 'application/json'
        return {'url': url, 'method': method, 'body': body, 'headers': headers}

    def handle_errors(self, httpCode: int, reason: str, url: str, method: str, headers: dict, body: str, response, requestHeaders, requestBody):
        if httpCode == 404 and url.find('/v3/exchanges/') >= 0:
            raise OrderNotFound(self.id + ' order not found')
        if response is None:
            return None
        code = self.safe_integer(response, 'code')
        error = self.safe_string(response, 'error')
        message = self.safe_string(response, 'message')
        if error is not None or (code is not None and code >= 400):
            if httpCode == 401 or code == 401 or error == 'Unauthorized':
                raise AuthenticationError(self.id + ' ' + body)
            if httpCode == 404 or code == 404 or error == 'Not Found':
                if url.find('/v3/exchanges/') >= 0:
                    raise OrderNotFound(self.id + ' ' + body)
                raise BadSymbol(self.id + ' ' + body)
            if httpCode == 422 or code == 422:
                raise InvalidOrder(self.id + ' ' + body)
            if httpCode == 400 or code == 400:
                raise BadRequest(self.id + ' ' + body)
            raise ExchangeError(self.id + ' ' + body)
        if message is not None and httpCode >= 400:
            if httpCode == 401 or httpCode == 403:
                raise AuthenticationError(self.id + ' ' + body)
            raise BadRequest(self.id + ' ' + body)
        return None
